class Solution {
    public ListNode mergeNodes(ListNode head){
        ListNode dummy=new ListNode(),tail=dummy;
        int sum=0;
        for(ListNode node=head.next;node!=null;node=node.next)if(node.val==0){
            tail.next=new ListNode(sum);
            tail=tail.next;
            sum=0;
        }else sum+=node.val;
        return dummy.next;
    }
}

code.kotlin:
class Solution {
    fun mergeNodes(head:ListNode?):ListNode?{
        val dummy=ListNode(0);
        var tail=dummy;
        var sum=0;
        var node=head!!.next;
        while(node!=null){
            if(node.`val`==0){
                tail.next=ListNode(sum);
                tail=tail.next!!;
                sum=0
            }else sum+=node.`val`;
            node=node.next
        };
        return dummy.next
    }
}

